"""Readable selector comparison from frozen decisions and source scores."""
import argparse,collections,json,math,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from nfl_v2.shared_subgroups import write,sha,now
from tools.numerical_championship import csvwrite
from tools.chronological_category_selector import POLICIES

def main(a):
 b=a.output;p=json.loads((b/'FROZEN_PROTOCOL.json').read_bytes());scores=json.loads((b/'SCORES.json').read_bytes());decisions=json.loads((b/'DECISIONS.json').read_bytes());by=collections.defaultdict(dict)
 for r in scores:by[r['target']][r['procedure_id'].split(':')[-1]]=r
 comparisons=[];lines=['# Chronological category-selection policy: prior-season versus current score memory','', 'All twelve categories, fixed2026 regular-season Weeks1–7/107games. This is an exposed historical reconstruction using120 exact H-MULTI output recipes with complete2025and2026 weekly evidence. It adds no fits, new forecasts or independently observed games. It is **not an original issued policy or fresh prospective confirmation**. Method-selection performance is separate from static-method rankings and from Over/Under pick selection.','', '**Result:** earlier available current-season score memory beats frozen2025best in4categories and loses8. Pooled2025+available2026 memory improves passingyards, loses passingattempts/completions and ties the other9categories. No universal memory winner is established.','', '| Category | n | Frozen2025best | Earlier2026score-memory | Delta vs frozen | Pooledprior+current | Delta vs frozen |','|---|---:|---:|---:|---:|---:|---:|']
 for target,rs in sorted(by.items()):
  metric='brier'if target=='anytime_td'else'mae';base=rs[POLICIES[0]][metric];n=rs[POLICIES[0]]['n'];cur=rs[POLICIES[1]][metric];pool=rs[POLICIES[2]][metric];lines.append(f'| {target} | {n} | {base:.6f} | {cur:.6f} | {cur-base:+.6f} | {pool:.6f} | {pool-base:+.6f} |')
  for policy in POLICIES[1:]:
   aa={r['evaluation_week']:r for r in decisions if r['target']==target and r['policy_id']==policy};bb={r['evaluation_week']:r for r in decisions if r['target']==target and r['policy_id']==POLICIES[0]};weekly={str(w):dict(n=aa[w]['n'],loss_difference_sum=aa[w]['n']*(aa[w]['native_loss']-bb[w]['native_loss']))for w in range(1,8)}
   comparisons.append(dict(target=target,metric=metric,policy=policy,comparator=POLICIES[0],n=n,selected_policy_native_loss=rs[policy][metric],comparator_native_loss=base,delta=rs[policy][metric]-base,relative_error_change=(rs[policy][metric]-base)/base,weekly_paired_sums_counts=weekly,week_clusters=7,unique_games=107,week_interval=None,week_interval_status='INSUFFICIENT_WEEK_CLUSTERS',game_sensitivity_status='NOT_ESTIMATED_FROM_AGGREGATE_ONLY_WEEKLY_SCORES',source='Exact common query/support/label values independently qualified; sums use source weekly losses and n, not average of weekly rates',selection_limit='Exposed retrospective selector,120outputrecipes not120independent learners; multiplicity notadjusted'))
 lines+=['','Native errors are MAE except anytime rushing-or-receiving TD, which uses Brier. Rows and categories are not independent trials. With only seven current week clusters, the registered minimum for week-bootstrap uncertainty is unmet; no significant or universal winner is claimed. Exact common membership is checked for all3000 recipe/week cells across2025+2026, including actual **values**, not merely equal row counts.','', '## What the policies actually knew','', 'At each weekly earliest-game fitting origin, an entire scoring week becomes eligible only after its **last game kickoff+7days is strictly earlier than that origin**. Current score memory is empty inWeeks1and2, then[1] atWeek3,[1,2] atWeek4,…,[1–5] atWeek7. It never uses Week6 or7 outcomes to choose a Week7 procedure. The fixedprior policy uses only the complete2025 score panel. The pooled policy weights2025andeligible2026 by their actual supported outcome counts.','', 'Current-memory startup uses the named base Leaf-CDF H-MULTI lower median (or event law for anytimeTD). All candidate forecasts themselves are H-MULTI with older feature memory. Thus this is **current-season performance memory for choosing among historically trained forecasts**, not a strict current-football-information model. Ties within1e−12 use the frozen stable target/procedure/product ID ordering; no hindsight weekly winner or posthoc support gate is used.','', 'The passing-yard current-memory sequence uses Leaf-CDF forWeeks1–4, then HGB absolute-error forWeeks5–7, yielding66.729270 MAE. Frozen2025best uses HGB squared-error throughout, yielding68.732925. Its improvement is about2.003655yards (2.92%), with seven week clusters and prior research exposure. The static hindsight current HGB absolute-error score66.117313 remains a separate descriptive result.','', 'Rushing-attempt current-memory3.049763 improves the fixed2025base Leaf-CDF3.059242 by0.009479carries. That composite-policy result is separate from the static D1observed score3.058057 and lacks untouched prospective confirmation. Adverse results remain visible: chartPPR4.589546 versus4.502391, anytimeTD Brier0.145145 versus0.143144, combinedyards20.469324 versus20.125661.','', '## Scope, retention and next action','', 'The roster excludes46current exact recipes lacking complete corresponding2025orcurrent weekly evidence. In particular, D1/D2have no older-season evaluation and are not silently replaced with base Leaf-CDF. Mean/median views are selectable output recipes, not separately counted model families. Current statistical outcomes are current-vintage with inherited availability assumptions, and query features use registered kickoff cutoffs; none is relabelled T-minus90 or originally issued.','', 'All inference/model/prediction evidence is reused. Source values and joins are checked from retained raw files; no new private row-level backlog is created. The preserved selector-v1failure was a chart-procedure reference-prefix error before any policy metrics; corrected selector-v2uses the exact registered chart/base mechanism. Main numerical-v1Infinity serialization failure is separately retained.','', 'No production action is recommended solely from this policy comparison. The next qualified test is later frozen category assignments using compatible captured forecasts, source cutoffs and retained-owner admission, with current/frozen/pooled controls all preserved. No official capture, scheduler, merge, deployment or website selection was changed.','', '[Frozen protocol/roster/source scores](FROZEN_PROTOCOL.json) · [Every earlier-only weekly decision](DECISIONS.csv) · [Policy scores and precision counts](POLICY_COMPARISON.csv) · [Paired weekly loss differences](POLICY_PAIRED_COMPARISONS.csv) · [Exact membership/label admission](EXACT_MASK_ADMISSION.json) · [Execution receipt](RUN_RECEIPT.json)']
 write(b/'POLICY_PAIRED_COMPARISONS.json',comparisons);csvwrite(b/'POLICY_PAIRED_COMPARISONS.csv',comparisons);(b/'README.md').write_text('\n'.join(lines)+'\n');write(b/'REPORT_RECEIPT.json',dict(at=now(),source_score_sha256=sha(b/'SCORES.json'),source_decisions_sha256=sha(b/'DECISIONS.json'),report_code_sha256=sha(__file__),new_NFL_fits=0,new_forecasts=0));print(json.dumps(dict(comparisons=len(comparisons),categories=len(by))))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);main(p.parse_args())
